import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`shipping-calculator`,heroTitle:`Calculate your shipping costs in minutes`,heroSubtitle:`Perplexity Computer researches every shipping method, calculates landed costs with duties and taxes, and delivers a fulfillment comparison table — automatically.`,inputUrlCta:`Calculate my shipping`,inputUrlPlaceholder:`e.g. AliExpress product URL`,inputUrlPrefill:`Go to {url} and perform a complete shipping cost analysis for this product. 1) Extract the product details including weight, dimensions, declared value, and HS code category. 2) Research all available shipping methods from the supplier to the US, EU (Germany as benchmark), and Australia — including ePacket, AliExpress Standard, CJ Packet, Yanwen, YunExpress, and any carrier options listed on the page. 3) For each shipping method and destination, calculate the full landed cost including product cost, shipping fee, estimated import duties, VAT/GST, and any customs processing fees. 4) Estimate delivery windows for each route — best case and worst case. 5) Flag any methods with tracking, insurance, or returns limitations. 6) Deliver a comparison table organized by destination region with columns for: shipping method, shipping cost, duties, taxes, total landed cost, estimated delivery window, tracking availability, and a recommended fulfillment method per region with reasoning. Include a summary with the lowest-cost and fastest option for each market.`,heroOverlaySteps:[`Extracting product details, weight, dimensions, and declared value`,`Researching all available shipping methods to the US, EU, and Australia`,`Calculating landed costs including duties, taxes, and carrier fees per route`,`Shipping comparison table with recommended fulfillment methods — ready to review`],generatingSteps:[`Visiting {url} to extract product specs, weight, and supplier shipping options`,`Designing an agent to research carrier rates, duties, and tax rules for US, EU, and AU`,`Configuring landed cost calculations for every shipping method and destination`,`Setting up comparison table with delivery windows and fulfillment recommendations`],featureSectionTitle:`From product URL to shipping playbook`,featureCardTitles:[`Connects to your dropshipping stack`,`Outputs you can price with`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Shopify, Google Sheets, Airtable, Notion — Computer plugs into your tools so shipping data flows straight into your store and pricing models.`,`Landed cost breakdowns by region. Duty and tax estimates. Carrier comparison tables. Delivery window ranges. Recommended fulfillment method per market.`],capabilitySectionTitle:`Your logistics analyst, on autopilot`,capabilitySectionSubtitle:`Paste a product URL, step away, come back to a complete shipping cost breakdown.`,capabilityCards:[{title:`Shipping Research`,description:`Computer can research every available shipping method from AliExpress, CJ Dropshipping, and other suppliers — and pull rates, transit times, and tracking options for each.`},{title:`Landed Cost Calculation`,description:`Computer can calculate the full landed cost per route — including product cost, shipping fees, import duties, VAT/GST, and customs processing charges.`},{title:`Fulfillment Recommendations`,description:`Computer can analyze cost, speed, and reliability tradeoffs — and recommend the best fulfillment method for each destination market.`},{title:`Connect Your Tools`,description:`Computer can push shipping data to Google Sheets, Airtable, Shopify, and Notion — so your pricing spreadsheets and store settings stay in sync.`},{title:`Remember & Learn`,description:`Computer can remember your preferred carriers, margin targets, and past product analyses — so every new calculation builds on your shipping history.`},{title:`Monitor & Alert`,description:`Computer can re-check carrier rates and duty thresholds on a schedule — and alert you when shipping costs change or faster routes become available.`}]});export{t as default};
